import { Helmet } from 'react-helmet-async';

interface SEOProps {
  title?: string;
  description?: string;
  keywords?: string;
  ogImage?: string;
  ogUrl?: string;
  twitterCard?: string;
  twitterImage?: string;
}

const SEO = ({
  title = 'SolDrop - Decentralized Token Distribution Platform',
  description = 'SolDrop is a revolutionary decentralized token distribution platform on Solana blockchain. Create, manage, and distribute tokens with ease.',
  keywords = 'solana, blockchain, token distribution, cryptocurrency, defi, solana tokens, token launch, crypto platform',
  ogImage = '/og-image.png',
  ogUrl = 'https://soldrop.io',
  twitterCard = 'summary_large_image',
  twitterImage = '/twitter-image.png'
}: SEOProps) => {
  const siteTitle = title === 'SolDrop - Decentralized Token Distribution Platform' 
    ? title 
    : `${title} | SolDrop`;

  return (
    <Helmet>
      {/* Basic Meta Tags */}
      <title>{siteTitle}</title>
      <meta name="description" content={description} />
      <meta name="keywords" content={keywords} />
      
      {/* Open Graph Meta Tags */}
      <meta property="og:title" content={siteTitle} />
      <meta property="og:description" content={description} />
      <meta property="og:image" content={ogImage} />
      <meta property="og:url" content={ogUrl} />
      <meta property="og:type" content="website" />
      
      {/* Twitter Meta Tags */}
      <meta name="twitter:card" content={twitterCard} />
      <meta name="twitter:title" content={siteTitle} />
      <meta name="twitter:description" content={description} />
      <meta name="twitter:image" content={twitterImage} />
      
      {/* Additional Meta Tags */}
      <meta name="viewport" content="width=device-width, initial-scale=1.0" />
      <meta name="robots" content="index, follow" />
      <meta name="language" content="English" />
      <meta name="revisit-after" content="7 days" />
      <meta name="author" content="SolDrop" />
      
      {/* Favicon */}
      <link rel="icon" type="image/png" href="/favicon.png" />
      <link rel="apple-touch-icon" href="/apple-touch-icon.png" />
      
      {/* Canonical URL */}
      <link rel="canonical" href={ogUrl} />
    </Helmet>
  );
};

export default SEO; 