import React from 'react';
import {
  Box,
  Container,
  Heading,
  Text,
  VStack,
  Button,
  Code,
  useClipboard,
  useToast,
  useColorModeValue,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Badge,
  HStack,
  Link,
  Skeleton,
} from '@chakra-ui/react';
import { FaCopy, FaExternalLinkAlt, FaGithub } from 'react-icons/fa';
import { useToken } from '../context/TokenContext';

const ContractInfo = ({ title, value }: { title: string; value: string }) => {
  const bgColor = useColorModeValue('white', 'gray.800');
  const borderColor = useColorModeValue('gray.200', 'gray.700');

  return (
    <Box
      p={6}
      bg={bgColor}
      rounded="xl"
      shadow="lg"
      border="1px solid"
      borderColor={borderColor}
    >
      <Text fontWeight="bold" mb={2}>{title}</Text>
      <Code p={2} borderRadius="md" display="block">
        {value}
      </Code>
    </Box>
  );
};

const Contract = () => {
  const { tokenData, isLoading } = useToken();
  const tokenMintAddress = '9t2FDVKv7HJwCtocJ15k27NDyLBEpcWPFUHRoqzdmoon';
  const { onCopy } = useClipboard(tokenMintAddress);
  const toast = useToast();
  const bgColor = useColorModeValue('gray.50', 'gray.900');
  const textColor = useColorModeValue('gray.600', 'gray.300');
  const boxBgColor = useColorModeValue('white', 'gray.800');

  const contractInfo = {
    address: tokenMintAddress,
    network: 'Solana Mainnet',
    verified: true,
    creator: '0x1234...5678',
    totalSupply: tokenData ? `${tokenData.totalSupply.toLocaleString()} SOLDROP` : '0 SOLDROP',
    holders: tokenData ? tokenData.holders.toLocaleString() : '0',
  };

  const recentTransactions = [
    { hash: '0xabc...123', type: 'Transfer', amount: '1000 SOLDROP', time: '2 mins ago' },
    { hash: '0xdef...456', type: 'Reward', amount: '0.5 SOL', time: '5 mins ago' },
    { hash: '0xghi...789', type: 'Stake', amount: '500 SOLDROP', time: '10 mins ago' },
  ];

  const handleCopy = () => {
    onCopy();
    toast({
      title: 'Copied!',
      description: 'Contract address copied to clipboard',
      status: 'success',
      duration: 2000,
      isClosable: true,
    });
  };

  if (isLoading) {
    return (
      <Box bg={bgColor} minH="100vh" py={20}>
        <Container maxW="container.xl">
          <VStack spacing={8} align="stretch">
            <Box textAlign="center">
              <Skeleton height="60px" width="300px" mx="auto" mb={6} />
              <Skeleton height="24px" width="800px" mx="auto" />
            </Box>
            <Skeleton height="200px" />
            <Skeleton height="200px" />
          </VStack>
        </Container>
      </Box>
    );
  }

  return (
    <Box bg={bgColor} minH="100vh" py={20}>
      <Container maxW="container.xl">
        <Heading
          as="h1"
          size="2xl"
          mb={6}
          textAlign="center"
          bgGradient="linear(to-r, blue.400, purple.500)"
          bgClip="text"
        >
          Smart Contract
        </Heading>

        <Text fontSize="xl" textAlign="center" mb={10} maxW="3xl" mx="auto">
          Verified and audited smart contract for secure token distribution
        </Text>

        <VStack spacing={8} align="stretch">
          <ContractInfo
            title="Token Contract Address"
            value={contractInfo.address}
          />

          <Box p={6} bg={boxBgColor} rounded="xl" shadow="lg">
            <Heading size="md" mb={4}>Contract Verification</Heading>
            <VStack align="start" spacing={4}>
              <HStack>
                <Button
                  leftIcon={<FaGithub />}
                  colorScheme="gray"
                  variant="outline"
                  onClick={() => window.open('https://github.com/soldrop/contracts', '_blank')}
                >
                  View Source Code
                </Button>
                <Button
                  leftIcon={<FaExternalLinkAlt />}
                  colorScheme="blue"
                  variant="outline"
                  onClick={() => window.open(`https://solscan.io/token/${tokenMintAddress}`, '_blank')}
                >
                  View on Solscan
                </Button>
                <Button
                  leftIcon={<FaCopy />}
                  colorScheme="green"
                  variant="outline"
                  onClick={handleCopy}
                >
                  Copy Address
                </Button>
              </HStack>
              <Text>
                Our smart contracts have been audited by leading security firms and are
                verified on the Solana blockchain. You can view the source code on GitHub
                and verify the contract on Solscan.
              </Text>
            </VStack>
          </Box>

          <Box p={6} bg={boxBgColor} rounded="xl" shadow="lg">
            <Heading size="md" mb={4}>Contract Statistics</Heading>
            <Table variant="simple">
              <Thead>
                <Tr>
                  <Th>Metric</Th>
                  <Th>Value</Th>
                </Tr>
              </Thead>
              <Tbody>
                <Tr>
                  <Td>Total Supply</Td>
                  <Td>{contractInfo.totalSupply}</Td>
                </Tr>
                <Tr>
                  <Td>Holders</Td>
                  <Td>{contractInfo.holders}</Td>
                </Tr>
                <Tr>
                  <Td>Network</Td>
                  <Td>{contractInfo.network}</Td>
                </Tr>
                <Tr>
                  <Td>Verification Status</Td>
                  <Td>
                    <Badge colorScheme={contractInfo.verified ? 'green' : 'red'}>
                      {contractInfo.verified ? 'Verified' : 'Unverified'}
                    </Badge>
                  </Td>
                </Tr>
              </Tbody>
            </Table>
          </Box>
        </VStack>
      </Container>
    </Box>
  );
};

export default Contract; 