import {
  Box,
  Button,
  Flex,
  HStack,
  IconButton,
  Menu as ChakraMenu,
  MenuItem,
  MenuList,
  useColorMode,
  useColorModeValue,
  useDisclosure
} from '@chakra-ui/react';
import { HamburgerIcon, MoonIcon, SunIcon, CloseIcon } from '@chakra-ui/icons';
import { Link as RouterLink, useLocation } from 'react-router-dom';
import { useWallet } from '../context/WalletContext';

const Links = [
  { name: 'Home', path: '/' },
  { name: 'About', path: '/about' },
  { name: 'Tokenomics', path: '/tokenomics' },
  { name: 'Roadmap', path: '/roadmap' },
  { name: 'Contract', path: '/contract' },
];

const NavLink = ({ children, to }: { children: React.ReactNode; to: string }) => {
  const location = useLocation();
  const isActive = location.pathname === to;
  const hoverBg = useColorModeValue('gray.200', 'gray.700');
  const activeBg = useColorModeValue('gray.200', 'gray.700');
  
  return (
    <RouterLink to={to}>
      <Box
        px={2}
        py={1}
        rounded={'md'}
        _hover={{
          textDecoration: 'none',
          bg: hoverBg,
        }}
        bg={isActive ? activeBg : 'transparent'}
      >
        {children}
      </Box>
    </RouterLink>
  );
};

const Navigation = () => {
  const { isOpen, onOpen, onClose } = useDisclosure();
  const { colorMode, toggleColorMode } = useColorMode();
  const { isConnected, connect, disconnect, publicKey } = useWallet();

  const handleWalletAction = () => {
    if (isConnected) {
      disconnect();
    } else {
      connect();
    }
  };

  return (
    <Box bg={useColorModeValue('gray.100', 'gray.900')} px={4} position="fixed" w="100%" zIndex="sticky">
      <Flex h={16} alignItems={'center'} justifyContent={'space-between'}>
        <IconButton
          size={'md'}
          icon={isOpen ? <CloseIcon /> : <HamburgerIcon />}
          aria-label={'Open Menu'}
          display={{ md: 'none' }}
          onClick={isOpen ? onClose : onOpen}
        />
        <HStack spacing={8} alignItems={'center'}>
          <Box fontWeight="bold" fontSize="xl">SolDrop</Box>
          <HStack as={'nav'} spacing={4} display={{ base: 'none', md: 'flex' }}>
            {Links.map((link) => (
              <NavLink key={link.path} to={link.path}>
                {link.name}
              </NavLink>
            ))}
          </HStack>
        </HStack>
        <Flex alignItems={'center'}>
          <Button
            onClick={handleWalletAction}
            variant="solid"
            colorScheme="blue"
            mr={4}
          >
            {isConnected 
              ? `${publicKey?.toString().slice(0, 4)}...${publicKey?.toString().slice(-4)}`
              : 'Connect Wallet'
            }
          </Button>
          <IconButton
            aria-label="Toggle color mode"
            icon={colorMode === 'light' ? <MoonIcon /> : <SunIcon />}
            onClick={toggleColorMode}
          />
        </Flex>
      </Flex>

      {isOpen ? (
        <Box pb={4} display={{ md: 'none' }}>
          <ChakraMenu>
            <MenuList>
              {Links.map((link) => (
                <MenuItem key={link.path} as={RouterLink} to={link.path}>
                  {link.name}
                </MenuItem>
              ))}
            </MenuList>
          </ChakraMenu>
        </Box>
      ) : null}
    </Box>
  );
};

export default Navigation; 