import React from 'react';
import {
  Box,
  Container,
  Heading,
  Text,
  VStack,
  SimpleGrid,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  useColorModeValue,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Progress,
  Skeleton,
} from '@chakra-ui/react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts';
import { useToken } from '../context/TokenContext';

const Tokenomics = () => {
  const { tokenData, isLoading } = useToken();
  const bgColor = useColorModeValue('white', 'gray.800');
  const textColor = useColorModeValue('gray.600', 'gray.300');
  const cardBg = useColorModeValue('white', 'gray.700');

  const tokenDistribution = [
    { name: 'Community Rewards', value: 40, color: '#3182CE' },
    { name: 'Liquidity Pool', value: 25, color: '#38A169' },
    { name: 'Development', value: 15, color: '#D69E2E' },
    { name: 'Marketing', value: 10, color: '#805AD5' },
    { name: 'Team', value: 10, color: '#E53E3E' },
  ];

  const tokenMetrics = [
    { 
      label: 'Total Supply', 
      value: tokenData ? tokenData.totalSupply.toLocaleString() : '0',
      helpText: 'Fixed supply' 
    },
    { 
      label: 'Circulating Supply', 
      value: tokenData ? tokenData.circulatingSupply.toLocaleString() : '0',
      helpText: `${((tokenData?.circulatingSupply || 0) / (tokenData?.totalSupply || 1) * 100).toFixed(1)}% of total` 
    },
    { 
      label: 'Market Cap', 
      value: tokenData ? `$${tokenData.marketCap.toLocaleString()}` : '$0',
      helpText: 'Total value locked' 
    },
    { 
      label: 'Holders', 
      value: tokenData ? tokenData.holders.toLocaleString() : '0',
      helpText: 'Growing community' 
    },
  ];

  const vestingSchedule = [
    { phase: 'Team', allocation: '10%', vesting: '24 months', cliff: '12 months' },
    { phase: 'Development', allocation: '15%', vesting: '18 months', cliff: '6 months' },
    { phase: 'Marketing', allocation: '10%', vesting: '12 months', cliff: '3 months' },
    { phase: 'Community Rewards', allocation: '40%', vesting: 'N/A', cliff: 'N/A' },
    { phase: 'Liquidity Pool', allocation: '25%', vesting: 'N/A', cliff: 'N/A' },
  ];

  if (isLoading) {
    return (
      <Box bg={bgColor} minH="100vh" py={20}>
        <Container maxW="container.xl">
          <VStack spacing={12} align="stretch">
            <Box textAlign="center">
              <Skeleton height="60px" width="300px" mx="auto" mb={6} />
              <Skeleton height="24px" width="800px" mx="auto" />
            </Box>
            <SimpleGrid columns={{ base: 1, md: 2, lg: 4 }} spacing={8}>
              {[1, 2, 3, 4].map((i) => (
                <Box key={i} p={6} borderRadius="lg" boxShadow="lg" bg={cardBg}>
                  <Skeleton height="20px" mb={2} />
                  <Skeleton height="40px" mb={2} />
                  <Skeleton height="16px" />
                </Box>
              ))}
            </SimpleGrid>
          </VStack>
        </Container>
      </Box>
    );
  }

  return (
    <Box bg={bgColor} minH="100vh" py={20}>
      <Container maxW="container.xl">
        <VStack spacing={12} align="stretch">
          <Box textAlign="center">
            <Heading as="h1" size="2xl" mb={6}>
              Tokenomics
            </Heading>
            <Text fontSize="xl" color={textColor} maxW="800px" mx="auto">
              Understanding the SOLDROP token economics, distribution, and vesting schedule
              to ensure sustainable growth and value for our community.
            </Text>
          </Box>

          <SimpleGrid columns={{ base: 1, md: 2, lg: 4 }} spacing={8}>
            {tokenMetrics.map((metric, index) => (
              <Box
                key={index}
                p={6}
                borderRadius="lg"
                boxShadow="lg"
                bg={cardBg}
              >
                <Stat>
                  <StatLabel color={textColor}>{metric.label}</StatLabel>
                  <StatNumber fontSize="3xl">{metric.value}</StatNumber>
                  <StatHelpText>{metric.helpText}</StatHelpText>
                </Stat>
              </Box>
            ))}
          </SimpleGrid>

          <Box
            p={8}
            borderRadius="lg"
            boxShadow="xl"
            bg={cardBg}
            height="400px"
          >
            <Heading size="md" mb={6}>Token Distribution</Heading>
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={tokenDistribution}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {tokenDistribution.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </Box>

          <Box
            p={8}
            borderRadius="lg"
            boxShadow="xl"
            bg={cardBg}
          >
            <Heading size="md" mb={6}>Vesting Schedule</Heading>
            <Table variant="simple">
              <Thead>
                <Tr>
                  <Th>Phase</Th>
                  <Th>Allocation</Th>
                  <Th>Vesting Period</Th>
                  <Th>Cliff</Th>
                </Tr>
              </Thead>
              <Tbody>
                {vestingSchedule.map((schedule, index) => (
                  <Tr key={index}>
                    <Td>{schedule.phase}</Td>
                    <Td>{schedule.allocation}</Td>
                    <Td>{schedule.vesting}</Td>
                    <Td>{schedule.cliff}</Td>
                  </Tr>
                ))}
              </Tbody>
            </Table>
          </Box>

          <Box
            p={8}
            borderRadius="lg"
            boxShadow="xl"
            bg={cardBg}
          >
            <VStack spacing={6} align="stretch">
              <Heading size="md">Token Utility</Heading>
              <Text color={textColor}>
                The SOLDROP token serves multiple purposes within our ecosystem:
              </Text>
              <VStack spacing={4} align="start">
                <Text color={textColor}>• Governance rights for protocol decisions</Text>
                <Text color={textColor}>• Staking rewards and incentives</Text>
                <Text color={textColor}>• Access to premium features and services</Text>
                <Text color={textColor}>• Community voting power</Text>
                <Text color={textColor}>• Fee discounts on platform services</Text>
              </VStack>
            </VStack>
          </Box>
        </VStack>
      </Container>
    </Box>
  );
};

export default Tokenomics; 