import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { useToast } from '@chakra-ui/react';
import { Connection, PublicKey } from '@solana/web3.js';

interface PhantomProvider {
  isPhantom: boolean;
  connect: () => Promise<{ publicKey: { toString: () => string } }>;
  disconnect: () => Promise<void>;
}

declare global {
  interface Window {
    solana?: PhantomProvider;
  }
}

interface WalletContextType {
  wallet: PhantomProvider | null;
  publicKey: PublicKey | null;
  isConnected: boolean;
  connect: () => Promise<void>;
  disconnect: () => Promise<void>;
  connection: Connection;
}

const WalletContext = createContext<WalletContextType | undefined>(undefined);

export const useWallet = () => {
  const context = useContext(WalletContext);
  if (!context) {
    throw new Error('useWallet must be used within a WalletProvider');
  }
  return context;
};

interface WalletProviderProps {
  children: ReactNode;
}

export const WalletProvider: React.FC<WalletProviderProps> = ({ children }) => {
  const [wallet, setWallet] = useState<any>(null);
  const [publicKey, setPublicKey] = useState<PublicKey | null>(null);
  const [isConnected, setIsConnected] = useState(false);
  const toast = useToast();

  // Initialize Solana connection
  const connection = new Connection(
    process.env.REACT_APP_SOLANA_RPC_URL || 'https://api.mainnet-beta.solana.com',
    'confirmed'
  );

  useEffect(() => {
    // Check if Phantom is installed
    const checkIfWalletIsInstalled = async () => {
      try {
        if ('solana' in window && window.solana) {
          const provider = window.solana;
          if (provider.isPhantom) {
            setWallet(provider);
          }
        }
      } catch (error) {
        console.error('Error checking wallet installation:', error);
      }
    };

    checkIfWalletIsInstalled();
  }, []);

  const connect = async () => {
    try {
      if (!wallet) {
        toast({
          title: 'Wallet not found',
          description: 'Please install Phantom wallet',
          status: 'error',
          duration: 5000,
          isClosable: true,
        });
        return;
      }

      const response = await wallet.connect();
      setPublicKey(new PublicKey(response.publicKey.toString()));
      setIsConnected(true);
      
      toast({
        title: 'Wallet connected',
        description: 'Successfully connected to Phantom wallet',
        status: 'success',
        duration: 5000,
        isClosable: true,
      });
    } catch (error) {
      console.error('Error connecting wallet:', error);
      toast({
        title: 'Connection failed',
        description: 'Failed to connect to wallet',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  const disconnect = async () => {
    try {
      if (wallet) {
        await wallet.disconnect();
        setPublicKey(null);
        setIsConnected(false);
        
        toast({
          title: 'Wallet disconnected',
          description: 'Successfully disconnected from wallet',
          status: 'info',
          duration: 5000,
          isClosable: true,
        });
      }
    } catch (error) {
      console.error('Error disconnecting wallet:', error);
      toast({
        title: 'Disconnection failed',
        description: 'Failed to disconnect from wallet',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  return (
    <WalletContext.Provider
      value={{
        wallet,
        publicKey,
        isConnected,
        connect,
        disconnect,
        connection,
      }}
    >
      {children}
    </WalletContext.Provider>
  );
};

export default WalletContext; 