import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { Connection, PublicKey } from '@solana/web3.js';
import { useWallet } from './WalletContext';
import { useToast } from '@chakra-ui/react';
import axios from 'axios';

interface TokenData {
  totalSupply: number;
  circulatingSupply: number;
  holders: number;
  price: number;
  marketCap: number;
  volume24h: number;
  priceChange24h: number;
  liquidity: number;
  metadata: {
    name: string;
    symbol: string;
    description?: string;
    image?: string;
    website?: string;
    twitter?: string;
    telegram?: string;
    discord?: string;
  };
  tradingMetrics: {
    buyCount24h: number;
    sellCount24h: number;
    uniqueTraders24h: number;
    averageTradeSize: number;
  };
}

interface TokenContextType {
  tokenData: TokenData | null;
  isLoading: boolean;
  error: string | null;
  refreshTokenData: () => Promise<void>;
}

const TokenContext = createContext<TokenContextType | undefined>(undefined);

export const useToken = () => {
  const context = useContext(TokenContext);
  if (!context) {
    throw new Error('useToken must be used within a TokenProvider');
  }
  return context;
};

interface TokenProviderProps {
  children: ReactNode;
}

export const TokenProvider: React.FC<TokenProviderProps> = ({ children }) => {
  const [tokenData, setTokenData] = useState<TokenData | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { connection } = useWallet();
  const toast = useToast();

  const fetchTokenData = async () => {
    setIsLoading(true);
    setError(null);
    try {
      // Token mint address
      const tokenMint = new PublicKey('9t2FDVKv7HJwCtocJ15k27NDyLBEpcWPFUHRoqzdmoon');
      
      // 1. Fetch basic token data from Solana
      const supply = await connection.getTokenSupply(tokenMint);
      const accounts = await connection.getProgramAccounts(
        new PublicKey('TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA'),
        {
          filters: [
            { dataSize: 165 },
            { memcmp: { offset: 0, bytes: tokenMint.toBase58() } },
          ],
        }
      );

      // 2. Fetch price data from Jupiter
      const jupiterResponse = await axios.get(
        `https://price.jup.ag/v4/price?ids=${tokenMint.toString()}`
      );
      const jupiterData = jupiterResponse.data.data[tokenMint.toString()];

      // 3. Fetch market data from DexScreener
      const dexscreenerResponse = await axios.get(
        `https://api.dexscreener.com/latest/dex/tokens/${tokenMint.toString()}`
      );
      const dexscreenerData = dexscreenerResponse.data.pairs?.[0] || {};

      // Calculate circulating supply
      const circulatingSupply = Number(supply.value.amount) / Math.pow(10, supply.value.decimals);
      
      const enhancedTokenData: TokenData = {
        totalSupply: circulatingSupply * 1.2, // Assuming 20% is burned/locked
        circulatingSupply,
        holders: accounts.length,
        price: jupiterData?.price || dexscreenerData?.priceUsd || 0,
        marketCap: circulatingSupply * (jupiterData?.price || dexscreenerData?.priceUsd || 0),
        volume24h: dexscreenerData?.volume?.h24 || 0,
        priceChange24h: dexscreenerData?.priceChange?.h24 || 0,
        liquidity: dexscreenerData?.liquidity?.usd || 0,
        metadata: {
          name: dexscreenerData?.baseToken?.name || '',
          symbol: dexscreenerData?.baseToken?.symbol || '',
          description: '',
          image: '',
          website: dexscreenerData?.baseToken?.website || '',
          twitter: dexscreenerData?.baseToken?.twitter || '',
          telegram: dexscreenerData?.baseToken?.telegram || '',
          discord: dexscreenerData?.baseToken?.discord || '',
        },
        tradingMetrics: {
          buyCount24h: dexscreenerData?.txns?.h24?.buys || 0,
          sellCount24h: dexscreenerData?.txns?.h24?.sells || 0,
          uniqueTraders24h: dexscreenerData?.txns?.h24?.trades || 0,
          averageTradeSize: dexscreenerData?.txns?.h24?.volume / (dexscreenerData?.txns?.h24?.trades || 1) || 0,
        },
      };

      setTokenData(enhancedTokenData);
    } catch (err) {
      console.error('Error fetching token data:', err);
      setError('Failed to fetch token data');
      toast({
        title: 'Error',
        description: 'Failed to fetch token data',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchTokenData();
    // Set up polling every 30 seconds
    const interval = setInterval(fetchTokenData, 30000);
    return () => clearInterval(interval);
  }, [connection]);

  return (
    <TokenContext.Provider
      value={{
        tokenData,
        isLoading,
        error,
        refreshTokenData: fetchTokenData,
      }}
    >
      {children}
    </TokenContext.Provider>
  );
};

export default TokenContext; 