import React from 'react';
import { Box, SimpleGrid, Stat, StatLabel, StatNumber, StatHelpText, Skeleton } from '@chakra-ui/react';
import { useToken } from '../context/TokenContext';

const TokenStats: React.FC = () => {
  const { tokenData, isLoading } = useToken();

  if (isLoading) {
    return (
      <SimpleGrid columns={[1, 2, 3]} spacing={8}>
        {[1, 2, 3].map((i) => (
          <Box key={i} bg="whiteAlpha.100" p={6} rounded="xl" backdropFilter="blur(10px)">
            <Skeleton height="20px" mb={2} />
            <Skeleton height="40px" mb={2} />
            <Skeleton height="16px" />
          </Box>
        ))}
      </SimpleGrid>
    );
  }

  return (
    <SimpleGrid columns={[1, 2, 3]} spacing={8}>
      <Box bg="whiteAlpha.100" p={6} rounded="xl" backdropFilter="blur(10px)">
        <Stat>
          <StatLabel color="whiteAlpha.700">SOLDROP Holders</StatLabel>
          <StatNumber color="soldrop.500">{tokenData?.holders.toLocaleString() || '0'}</StatNumber>
          <StatHelpText>Active Token Holders</StatHelpText>
        </Stat>
      </Box>
      <Box bg="whiteAlpha.100" p={6} rounded="xl" backdropFilter="blur(10px)">
        <Stat>
          <StatLabel color="whiteAlpha.700">Token Price</StatLabel>
          <StatNumber color="soldrop.500">${tokenData?.price.toFixed(6) || '0.00'}</StatNumber>
          <StatHelpText>24h Change: {tokenData?.priceChange24h.toFixed(2)}%</StatHelpText>
        </Stat>
      </Box>
      <Box bg="whiteAlpha.100" p={6} rounded="xl" backdropFilter="blur(10px)">
        <Stat>
          <StatLabel color="whiteAlpha.700">24h Volume</StatLabel>
          <StatNumber color="soldrop.500">${tokenData?.volume24h.toLocaleString() || '0'}</StatNumber>
          <StatHelpText>Total Trading Volume</StatHelpText>
        </Stat>
      </Box>
    </SimpleGrid>
  );
};

export default TokenStats;