import React from 'react';
import {
  Box,
  Container,
  Heading,
  Text,
  VStack,
  HStack,
  useColorModeValue,
} from '@chakra-ui/react';
import { FaCheckCircle, FaCircle } from 'react-icons/fa';

interface Milestone {
  quarter: string;
  title: string;
  description: string;
  completed: boolean;
}

const milestones: Milestone[] = [
  {
    quarter: 'Q1 2024',
    title: 'Platform Launch',
    description: 'Initial release of SolDrop platform with basic token distribution features',
    completed: true,
  },
  {
    quarter: 'Q2 2024',
    title: 'Enhanced Security',
    description: 'Implementation of advanced security measures and audit completion',
    completed: false,
  },
  {
    quarter: 'Q3 2024',
    title: 'Community Features',
    description: 'Launch of governance system and community voting mechanisms',
    completed: false,
  },
  {
    quarter: 'Q4 2024',
    title: 'Advanced Analytics',
    description: 'Integration of comprehensive analytics and reporting tools',
    completed: false,
  },
  {
    quarter: 'Q1 2025',
    title: 'Cross-chain Integration',
    description: 'Expansion to support multiple blockchain networks',
    completed: false,
  },
];

const RoadmapItem = ({ milestone }: { milestone: Milestone }) => {
  const bgColor = useColorModeValue('white', 'gray.800');
  const borderColor = useColorModeValue('gray.200', 'gray.700');

  return (
    <Box
      p={6}
      bg={bgColor}
      rounded="xl"
      shadow="lg"
      borderLeft="4px solid"
      borderColor={milestone.completed ? 'green.500' : 'blue.500'}
      position="relative"
    >
      <HStack spacing={4}>
        <Box>
          {milestone.completed ? (
            <FaCheckCircle color="#48BB78" size="24px" />
          ) : (
            <FaCircle color="#4299E1" size="24px" />
          )}
        </Box>
        <VStack align="start" spacing={2}>
          <HStack>
            <Text fontWeight="bold" color={useColorModeValue('gray.600', 'gray.400')}>
              {milestone.quarter}
            </Text>
            <Heading size="md">{milestone.title}</Heading>
          </HStack>
          <Text color={useColorModeValue('gray.600', 'gray.400')}>
            {milestone.description}
          </Text>
        </VStack>
      </HStack>
    </Box>
  );
};

const Roadmap = () => {
  const bgColor = useColorModeValue('gray.50', 'gray.900');

  return (
    <Box bg={bgColor} minH="100vh" py={20}>
      <Container maxW="container.xl">
        <Heading
          as="h1"
          size="2xl"
          mb={6}
          textAlign="center"
          bgGradient="linear(to-r, blue.400, purple.500)"
          bgClip="text"
        >
          Roadmap
        </Heading>

        <Text fontSize="xl" textAlign="center" mb={10} maxW="3xl" mx="auto">
          Our journey to revolutionize token distribution on the Solana blockchain
        </Text>

        <VStack spacing={6} align="stretch">
          {milestones.map((milestone, index) => (
            <RoadmapItem key={index} milestone={milestone} />
          ))}
        </VStack>

        <Box mt={10} textAlign="center">
          <Text fontSize="lg" color={useColorModeValue('gray.600', 'gray.400')}>
            Stay tuned for more updates and announcements as we continue to build
            and improve the SolDrop platform.
          </Text>
        </Box>
      </Container>
    </Box>
  );
};

export default Roadmap; 